// One-time backfill: push historical WooCommerce orders (id >= 13275, paid statuses)
// into Supabase public.web_purchases. Trigger by visiting any admin page with
// ?jd_run_backfill=1 while logged in as an administrator. Safe to re-run (upsert).
add_action( "admin_init", "jd_backfill_web_purchases" );

function jd_backfill_web_purchases() {
    if ( ! current_user_can( "manage_options" ) ) return;
    if ( ! isset( $_GET["jd_run_backfill"] ) ) return;

    $min_order_id = 13275;
    $sb_url = "https://misrdmmvukdpranxnqjq.supabase.co";
    $sb_key = "<SUPABASE_ANON_KEY>";
    $hdrs = array(
        "apikey"        => $sb_key,
        "Authorization" => "Bearer " . $sb_key,
        "Content-Type"  => "application/json",
        "Prefer"        => "resolution=merge-duplicates,return=minimal",
    );

    $order_ids = wc_get_orders( array(
        "limit"  => -1,
        "status" => array( "processing", "completed" ),
        "return" => "ids",
        "orderby" => "ID",
        "order"   => "ASC",
    ) );
    $order_ids = array_filter( $order_ids, function( $id ) use ( $min_order_id ) {
        return (int) $id >= $min_order_id;
    } );

    $rows = array();
    foreach ( $order_ids as $order_id ) {
        $order = wc_get_order( $order_id );
        if ( ! $order ) continue;
        $email  = $order->get_billing_email();
        $phone  = $order->get_billing_phone();
        $status = $order->get_status();
        $date   = $order->get_date_created() ? $order->get_date_created()->date( "c" ) : null;
        foreach ( $order->get_items() as $item ) {
            $rows[] = array(
                "order_id"     => (int) $order_id,
                "product_id"   => (int) $item->get_product_id(),
                "variation_id" => (int) $item->get_variation_id(),
                "product_name" => $item->get_name(),
                "email"        => $email,
                "phone"        => $phone,
                "order_status" => $status,
                "order_date"   => $date,
            );
        }
    }

    $chunks = array_chunk( $rows, 200 );
    $pushed = 0;
    $errors = array();
    foreach ( $chunks as $chunk ) {
        $resp = wp_remote_post( $sb_url . "/rest/v1/web_purchases?on_conflict=order_id,product_id,variation_id", array(
            "headers" => $hdrs,
            "body"    => wp_json_encode( $chunk ),
            "timeout" => 30,
        ) );
        if ( is_wp_error( $resp ) ) {
            $errors[] = $resp->get_error_message();
        } else {
            $code = wp_remote_retrieve_response_code( $resp );
            if ( $code >= 200 && $code < 300 ) {
                $pushed += count( $chunk );
            } else {
                $errors[] = "HTTP $code: " . wp_remote_retrieve_body( $resp );
            }
        }
    }

    wp_die(
        "Backfill done.<br>Orders scanned: " . count( $order_ids ) .
        "<br>Line-item rows pushed: " . $pushed .
        "<br>Errors: " . ( $errors ? "<pre>" . esc_html( implode( "\n", $errors ) ) . "</pre>" : "none" )
    );
}

/*
JEDDA JASTIP BACKFILL UTILITY
Jalan sekali lewat URL (admin only), scan order historis (completed dari
order id tertentu, refunded dari order id tertentu, exclude nama Agif/Dinda
di refund karena itu order test), filter cuma yang ada watched product,
kirim ke Supabase RPC yang sama dengan live hook.

Cara pakai (harus login sebagai admin):
/wp-admin/?jd_jastip_backfill=completed&start_id=4667&paged=1
/wp-admin/?jd_jastip_backfill=refunded&start_id=7894&paged=1
Klik link "Lanjut batch berikutnya" di bawah hasil sampai selesai.
*/


if ( ! function_exists( 'jd_jastip_get_watched_keywords' ) ) {
  function jd_jastip_get_watched_keywords() {
    $cached = get_transient( 'jd_jastip_watched_keywords' );
    if ( $cached !== false ) { return $cached; }
    $url = 'https://misrdmmvukdpranxnqjq.supabase.co/rest/v1/jastip_watched_products?active=eq.true&select=keyword';
    $resp = wp_remote_get( $url, array(
      'headers' => array(
        'apikey'        => '<SUPABASE_ANON_KEY>',
        'Authorization' => 'Bearer <SUPABASE_ANON_KEY>',
      ),
      'timeout' => 8,
    ) );
    if ( is_wp_error( $resp ) ) { return array(); }
    $body = json_decode( wp_remote_retrieve_body( $resp ), true );
    if ( ! is_array( $body ) ) { return array(); }
    $keywords = array_map( function( $row ) { return strtolower( $row['keyword'] ); }, $body );
    set_transient( 'jd_jastip_watched_keywords', $keywords, 5 * MINUTE_IN_SECONDS );
    return $keywords;
  }
}
add_action( 'admin_init', function() {
  if ( empty( $_GET['jd_jastip_backfill'] ) || ! current_user_can( 'manage_options' ) ) {
    return;
  }

  $status   = sanitize_text_field( $_GET['jd_jastip_backfill'] );
  $start_id = isset( $_GET['start_id'] ) ? (int) $_GET['start_id'] : 0;
  $paged    = isset( $_GET['paged'] ) ? max( 1, (int) $_GET['paged'] ) : 1;
  $batch    = 300;

  if ( ! in_array( $status, array( 'completed', 'refunded' ), true ) ) {
    wp_die( 'Status harus completed atau refunded.' );
  }

  $keywords = jd_jastip_get_watched_keywords();
  if ( empty( $keywords ) ) {
    wp_die( 'Watched products kosong, cek dulu di dashboard.' );
  }

  $orders = wc_get_orders( array(
    'status'  => array( $status ),
    'limit'   => $batch,
    'paged'   => $paged,
    'orderby' => 'ID',
    'order'   => 'ASC',
    'return'  => 'objects',
  ) );

  $scanned = 0;
  $sent = 0;
  $skipped_id = 0;
  $skipped_test = 0;
  $skipped_no_watch = 0;
  $errors = array();

  foreach ( $orders as $order ) {
    $scanned++;

    if ( $order->get_id() < $start_id ) {
      $skipped_id++;
      continue;
    }

    $full_name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );
    if ( $status === 'refunded' && ( stripos( $full_name, 'agif' ) !== false || stripos( $full_name, 'dinda' ) !== false ) ) {
      $skipped_test++;
      continue;
    }

    $products = array();
    $has_watched = false;
    foreach ( $order->get_items() as $item ) {
      $name = $item->get_name();
      $products[] = array( 'name' => $name, 'qty' => (int) $item->get_quantity() );
      $name_lower = strtolower( $name );
      foreach ( $keywords as $kw ) {
        if ( strpos( $name_lower, $kw ) !== false ) { $has_watched = true; break; }
      }
    }

    if ( ! $has_watched ) {
      $skipped_no_watch++;
      continue;
    }

    $recipient_name = trim( $order->get_shipping_first_name() . ' ' . $order->get_shipping_last_name() );
    if ( $recipient_name === '' ) { $recipient_name = $full_name; }
    $phone = method_exists( $order, 'get_shipping_phone' ) ? $order->get_shipping_phone() : '';
    if ( empty( $phone ) ) { $phone = $order->get_billing_phone(); }
    $address_raw = trim( $order->get_shipping_address_1() . ' ' . $order->get_shipping_address_2() );
    if ( $address_raw === '' ) { $address_raw = trim( $order->get_billing_address_1() . ' ' . $order->get_billing_address_2() ); }
    $city = $order->get_shipping_city() ?: $order->get_billing_city();
    $province = $order->get_shipping_state() ?: $order->get_billing_state();
    $postal = $order->get_shipping_postcode() ?: $order->get_billing_postcode();

    $payload = array(
      'p_order_no'       => (string) $order->get_order_number(),
      'p_recipient_name' => $recipient_name,
      'p_phone'          => $phone,
      'p_address_raw'    => $address_raw,
      'p_subdistrict'    => null,
      'p_city'           => $city,
      'p_province'       => $province,
      'p_postal_code'    => $postal,
      'p_products'       => $products,
    );

    $resp = wp_remote_request( 'https://misrdmmvukdpranxnqjq.supabase.co/rest/v1/rpc/jastip_ingest_order', array(
      'method'  => 'POST',
      'headers' => array(
        'Content-Type'  => 'application/json',
        'apikey'        => '<SUPABASE_ANON_KEY>',
        'Authorization' => 'Bearer <SUPABASE_ANON_KEY>',
      ),
      'body'    => wp_json_encode( $payload ),
      'timeout' => 15,
    ) );

    if ( is_wp_error( $resp ) ) {
      $errors[] = $order->get_order_number() . ': ' . $resp->get_error_message();
    } else {
      $sent++;
    }
  }

  $next_paged = $paged + 1;
  $next_url = admin_url( '?jd_jastip_backfill=' . $status . '&start_id=' . $start_id . '&paged=' . $next_paged );
  $done = ( count( $orders ) < $batch );

  echo '<html><body style="font-family:monospace;padding:40px;">';
  echo '<h2>Jastip Backfill — ' . esc_html( $status ) . ' (batch ' . esc_html( $paged ) . ')</h2>';
  echo '<p>Order di-scan halaman ini: ' . esc_html( $scanned ) . '</p>';
  echo '<p>Terkirim ke Supabase (ada watched product): ' . esc_html( $sent ) . '</p>';
  echo '<p>Dilewati (ID < start_id): ' . esc_html( $skipped_id ) . '</p>';
  echo '<p>Dilewati (test Agif/Dinda): ' . esc_html( $skipped_test ) . '</p>';
  echo '<p>Dilewati (tidak ada watched product): ' . esc_html( $skipped_no_watch ) . '</p>';
  if ( $errors ) {
    echo '<p style="color:red;">Error:</p><ul>';
    foreach ( $errors as $e ) { echo '<li>' . esc_html( $e ) . '</li>'; }
    echo '</ul>';
  }
  if ( $done ) {
    echo '<h3>Selesai — tidak ada order lagi di halaman berikutnya.</h3>';
  } else {
    echo '<p><a href="' . esc_url( $next_url ) . '">Lanjut batch berikutnya (batch ' . esc_html( $next_paged ) . ')</a></p>';
  }
  echo '</body></html>';
  exit;
} );

/*
JEDDA JASTIP EMAIL BACKFILL (targeted, run once)
Isi kolom email di jastip_orders untuk order_no yang lagi ada di daftar
perlu-direview sekarang, supaya dashboard-waitslist bisa cross-check
pakai email juga (bukan cuma HP). Hapus snippet ini setelah dipakai.
