  if ( ! isset($_GET['jd_jastip_email_backfill']) ) return;

  $order_nos = ["11891","11907","11933","11964","11979","12011","12015","12062","12063","12109","12204","12205","12258","12278","12332","12382","12384","12394","12544","12569","12692","12846","5440","5472","5572","5603","5674","5693","5701","5712","5753","5967","5969","5974","6002","6007","6021","6065","6081","6598","6600","6620","6630","6633","6635","6646","6653","6658","6665","6667","6668","6680","6683","6686","6693","6694","6697","6701","6717","6735","6738","6739","6747","6772","6788","6791","6795","6801","6802","6805","6816","6817","6825","6837","6851","6854","6861","6864","6865","6871","6872","6883","6884","6890","6893","6897","6903","6909","6912","6926","6929","6931","6938","6942","7894","8765","8936","9017","9020","9529","9530","9541","9542","9573","9740"];
  $supabase_url = 'https://misrdmmvukdpranxnqjq.supabase.co';
  $supabase_key = '<SUPABASE_ANON_KEY>';

  $updated = 0; $skipped = 0; $no_order = 0;
  foreach ($order_nos as $order_no) {
    $order = wc_get_order((int) $order_no);
