    $resp = wp_remote_request($supabase_url . '/rest/v1/jastip_orders?order_no=eq.' . rawurlencode($order_no), array(
      'method' => 'PATCH',
      'headers' => array(
        'apikey' => $supabase_key,
        'Authorization' => 'Bearer ' . $supabase_key,
        'Content-Type' => 'application/json',
      ),
      'body' => wp_json_encode(array('email' => $email, 'email_normalized' => $email_norm)),
      'timeout' => 15,
    ));
    if (!is_wp_error($resp)) $updated++;
  }

  echo '<html><body style="font-family:sans-serif;padding:24px;">';
  echo '<h2>Jastip Email Backfill</h2>';
  echo '<p>Total order_no: ' . count($order_nos) . '</p>';
  echo '<p>Berhasil update email: ' . $updated . '</p>';
  echo '<p>Dilewati (tidak ada email di order): ' . $skipped . '</p>';
  echo '<p>Order tidak ditemukan: ' . $no_order . '</p>';
  echo '</body></html>';
  exit;
});
